        event_end_time_obj = event_end_time(event)
        new_event_start_time_obj = datetime.strptime(new_event["date"], "%Y-%m-%d") + datetime.strptime(new_event["start_time"], "%H:%M")

        if new_event_start_time_obj < event_end_time_obj:
            return False

    return True

def calculate_average_monthly_savings(income, expenses):
    if len(income) != len(expenses) or len(income) != 12 or len(expenses) != 12:
        return None

    total_savings = 0
    for i in range(12):
        if not isinstance(income[i], (int, float)) or not isinstance(expenses[i], (int, float)) or income[i] < 0 or expenses[i] < 0:
            return None
        monthly_savings = income[i] - expenses[i]
        total_savings += monthly_savings

    if total_savings < 0:
        return None

    average_savings = total_savings / 12
    return average_savings

#include <iostream>
#include <vector>
#include <memory>
#include <algorithm>

struct Person {
    std::string name;
    int age;
};

int main() {
    std::vector<std::unique_ptr<Person>> people = {
        std::make_unique<Person>{ "Alice", 30 },
        std::make_unique<Person>{ "Bob", 25 },
        std::make_unique<Person>{ "Charlie", 35 }
    };

    // Sort people by age using a lambda as the comparator
    std::sort(people.begin(), people.end(),
        [](const std::unique_ptr<Person>& a, const std::unique_ptr<Person>& b) {
            return a->age < b->age;
        });

    // Range-based for loop to print each person
    for (const auto& person : people) {
        std::cout << person->name << " is " << person->age << " years old." << std::endl;
    }

    return 0;
}
